<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import UiStatePanel from'./UiStatePanel.vue';import ConfirmDialog from'./ConfirmDialog.vue';import'../provider-sources.css';
type State='loading'|'ready'|'empty'|'error'|'expired'|'forbidden'|'blocked';interface Provisioned{id:string;status:'draft'|'disabled'|'enabled';version:number}interface Source{code:string;name:string;access_mode:string;category:string;fields:string[];markets:string[];languages:string[];production_policy:string;policy_note:string;target_url:string;provisioned:Provisioned|null}const props=defineProps<{apiBaseUrl:string}>(),state=ref<State>('loading'),items=ref<Source[]>([]),requestId=ref(''),message=ref(''),saving=ref(''),confirm=ref<Source|null>(null),selected=ref<Source|null>(null),form=reactive({organization_id:'',workspace_id:'',query:'',csv_text:''}),failure=(s:number):State=>s===401?'expired':s===403?'forbidden':[408,425,429,502,503,504].includes(s)?'blocked':'error',enabled=computed(()=>items.value.filter(item=>item.provisioned?.status==='enabled'));
async function load(){state.value='loading';message.value='';try{const r=await fetch(`${props.apiBaseUrl}/platform/provider-sources`,{credentials:'include',headers:{accept:'application/json'}}),b=await r.json().catch(()=>null);requestId.value=b?.request_id??'';if(!r.ok){state.value=failure(r.status);return;}items.value=b.data;state.value=items.value.length?'ready':'empty';selected.value=enabled.value[0]??null;}catch{state.value='blocked';}}
async function write(path:string,body:unknown){saving.value=path;message.value='';try{const r=await fetch(`${props.apiBaseUrl}${path}`,{method:'POST',credentials:'include',headers:{'content-type':'application/json','idempotency-key':crypto.randomUUID()},body:JSON.stringify(body)}),b=await r.json().catch(()=>null);requestId.value=b?.request_id??'';if(!r.ok){message.value=b?.error?.action_hint??'操作未完成';return false;}return true;}catch{message.value='依赖不可用，未写入任何状态';return false;}finally{saving.value='';}}
async function provision(){const item=confirm.value;if(!item)return;if(await write(`/platform/provider-sources/${item.code}/provision`,{})){confirm.value=null;await load();}}
async function replay(){if(!selected.value?.provisioned)return;const body={organization_id:form.organization_id,workspace_id:form.workspace_id,...(selected.value.code==='google_news_search'?{query:form.query}:{csv_text:form.csv_text})};if(await write(`/platform/provider-sources/${selected.value.provisioned.id}/replays`,body))message.value='采集任务已进入 scheduled；可前往采集控制台跟踪。';}
onMounted(load);
</script>
<template><section class="source-center"><header><div><p>FIRST-PARTY SOURCE ADMISSION</p><h2>首批来源实现</h2><span>先登记为 disabled，再由所有者复核并显式启用；端点可用不代表生产授权。</span></div><a href="/platform-admin/collection">采集控制台 ↗</a></header><UiStatePanel v-if="!['ready','empty'].includes(state)" :kind="state" :request-id="requestId" @primary="load"/><template v-else><div class="source-metrics"><article><small>BUILT-IN SOURCES</small><strong>{{items.length}}</strong><span>固定合同，不接受任意 URL</span></article><article><small>PROVISIONED</small><strong>{{items.filter(x=>x.provisioned).length}}</strong><span>默认 disabled</span></article><article><small>ENABLED</small><strong>{{enabled.length}}</strong><span>所有者显式复核</span></article></div><section class="source-grid"><article v-for="item in items" :key="item.code"><header><span>{{item.category==='trend'?'↗':'▦'}}</span><div><small>{{item.access_mode}} · {{item.category}}</small><h3>{{item.name}}</h3></div><b :data-status="item.provisioned?.status??'catalog'">{{item.provisioned?.status??'catalog'}}</b></header><code>{{item.code}}</code><p>{{item.policy_note}}</p><dl><div><dt>市场 / 语言</dt><dd>{{item.markets.join(', ')}} / {{item.languages.join(', ')}}</dd></div><div><dt>字段</dt><dd>{{item.fields.join(' · ')}}</dd></div><div><dt>生产策略</dt><dd>{{item.production_policy}}</dd></div></dl><footer><button v-if="!item.provisioned" type="button" @click="confirm=item">登记为 disabled</button><a v-else href="/platform-admin/providers">在来源定义页复核 / 启用</a></footer></article></section><form class="source-replay" @submit.prevent="replay"><header><div><p>CONTROLLED REPLAY</p><h3>创建一次受控采集任务</h3></div><span>每批最多 20 条；原始证据先落盘</span></header><label>已启用来源<select v-model="selected" required><option :value="null" disabled>{{enabled.length?'选择来源':'没有已启用来源'}}</option><option v-for="item in enabled" :key="item.code" :value="item">{{item.name}}</option></select></label><label>组织 ID<input v-model="form.organization_id" required pattern="[0-9a-fA-F-]{36}"></label><label>工作区 ID<input v-model="form.workspace_id" required pattern="[0-9a-fA-F-]{36}"></label><label v-if="selected?.code==='google_news_search'" class="wide">关键词<input v-model="form.query" required maxlength="200" placeholder="例如 foldable desk lamp"></label><label v-else class="wide">CSV 内容<textarea v-model="form.csv_text" required rows="7" placeholder="external_id,title,price,currency,supplier_name,moq,canonical_url,observed_at"></textarea></label><footer><button type="submit" :disabled="!selected||Boolean(saving)">{{saving?'创建中…':'创建 scheduled 任务'}}</button><small>Google News 来源需先完成条款、频率与保存字段复核。</small></footer></form><p v-if="message" class="source-message" role="status">{{message}} <code v-if="requestId">{{requestId}}</code></p></template><ConfirmDialog :open="Boolean(confirm)" title="登记首批来源？" :description="`${confirm?.name??''} 将以 disabled 状态写入来源注册中心。`" impact="登记不会启动采集，也不会自动启用；所有者必须在来源定义页复核生产政策后显式启用。" confirm-label="登记来源" confirmation-text="确认登记" @cancel="confirm=null" @confirm="provision"/></section></template>
